-- Additive normalized specializations. Existing textual tracks remain historical snapshots.
ALTER TABLE tracks ADD COLUMN IF NOT EXISTS sort_order BIGINT NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS track_aliases(name TEXT PRIMARY KEY,track_id BIGINT NOT NULL REFERENCES tracks(id) DEFERRABLE INITIALLY IMMEDIATE);
INSERT INTO track_aliases(name,track_id) SELECT name,id FROM tracks ON CONFLICT (name) DO NOTHING;
CREATE TABLE IF NOT EXISTS track_nodes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,root_track_id BIGINT NOT NULL REFERENCES tracks(id) DEFERRABLE INITIALLY IMMEDIATE,parent_id BIGINT REFERENCES track_nodes(id) DEFERRABLE INITIALLY IMMEDIATE,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','archived')),sort_order BIGINT NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_track_nodes_parent ON track_nodes(root_track_id,parent_id,sort_order,id);
CREATE TABLE IF NOT EXISTS user_specializations(user_id BIGINT PRIMARY KEY REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,root_track_id BIGINT NOT NULL REFERENCES tracks(id) DEFERRABLE INITIALLY IMMEDIATE,node_id BIGINT REFERENCES track_nodes(id) DEFERRABLE INITIALLY IMMEDIATE,path_snapshot TEXT NOT NULL,updated_by BIGINT REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_user_specializations_node ON user_specializations(root_track_id,node_id);
CREATE TABLE IF NOT EXISTS teacher_specializations(user_id BIGINT NOT NULL REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,node_id BIGINT NOT NULL REFERENCES track_nodes(id) DEFERRABLE INITIALLY IMMEDIATE,created_by BIGINT NOT NULL REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,created_at TEXT NOT NULL,PRIMARY KEY(user_id,node_id));
INSERT INTO user_specializations(user_id,root_track_id,node_id,path_snapshot,updated_at) SELECT u.id,a.track_id,NULL,u.track,u.updated_at FROM users u JOIN track_aliases a ON a.name=u.track WHERE u.track<>'' ON CONFLICT(user_id) DO NOTHING;
